import logging

from ta_ue_plugin_android.uepc import adb_proxy
from ta_ue_plugin_android.uepc.ue_manager_exceptions import UnexpectedCpuTypeException

SERVICE_CALL_COMMAND = "service call phone"
SERVICE_DATA_COMMAND = "svc data {state}"
DISABLE_DATA_CONNECTIVITY_EXYNOS = 41
ENABLE_DATA_CONNECTIVITY_EXYNOS = 40
DISABLE_DATA_CONNECTIVITY_QUALCOMM = 30
ENABLE_DATA_CONNECTIVITY_QUALCOMM = 29
SERVICE_CALL_MODELS_CPU = ["SM-G977U", "SM-G977N", "SAMSUNG SM-G977N"]


class MobileDataHandler(object):
    """class used for handling mobile data settings"""

    def __init__(self, ue_model, ue_cpu, ue_serial, is_rooted, su_prefix, is_qcom_prototype, ue_manager_protocol_send_function):
        """Initializes mobileDataHandler with provided arguments"""
        self._ue_model = ue_model
        self._cpu = ue_cpu
        self._serial = ue_serial
        self._is_rooted = is_rooted
        self._su_prefix = su_prefix
        self._is_qcom_prototype = is_qcom_prototype
        self._protocol_send_function = ue_manager_protocol_send_function
        self.logger = logging.getLogger('ute_ue.uepc')
        self.logger.debug("{} created".format(__name__))

    def set_data_connectivity(self, enable=False):
        """Set mobile data connectivity on / off"""
        self.logger.debug("set data connectivity call")

        adb_shell_cmd = self._get_adb_shell_command(enable=enable)
        adb_proxy.adb_run_cmd(self._serial, "shell", [adb_shell_cmd])

    def _get_adb_shell_command(self, enable=False):
        if any([model in self._ue_model.upper() for model in SERVICE_CALL_MODELS_CPU]):
            return self._get_service_call_command(enable)
        return self._get_svc_data_command(enable)

    def _get_svc_data_command(self, enable):
        cmd = SERVICE_DATA_COMMAND.format(state="enable" if enable else "disable")
        if self._is_rooted:
            return self._add_su_prefix(self._su_prefix, cmd)
        return cmd

    def _get_service_call_command(self, enable):
        self.logger.debug("UE model {} requires usage of service calls in order to set mobile data."
                          .format(self._ue_model))
        return self._get_service_call_based_on_cpu_model(enable)

    def _get_service_call_based_on_cpu_model(self, enable):
        if "exynos" in self._cpu:
            self.logger.debug("UE cpu is {}, issuing exynos service calls".format(self._cpu))

            return "{} {}".format(SERVICE_CALL_COMMAND,
                                  ENABLE_DATA_CONNECTIVITY_EXYNOS if enable else DISABLE_DATA_CONNECTIVITY_EXYNOS)
        if "qcom" in self._cpu:
            self.logger.debug("UE cpu is {} issuing qualcomm service calls".format(self._cpu))
            return "{} {}".format(SERVICE_CALL_COMMAND,
                                  ENABLE_DATA_CONNECTIVITY_QUALCOMM if enable else DISABLE_DATA_CONNECTIVITY_QUALCOMM)
        raise UnexpectedCpuTypeException("Ue - {} got unexpected cpu type: {}! Please report this to "
                                         "ta_ue_plugin_android team!".format(self._ue_model, self._cpu))

    def _add_su_prefix(self, su_prefix, command):
        return "{} {}".format(su_prefix, command)
